function minimumCost(s) {
  // Shortest paths over all 2^n strings, stored as bit masks (bit j is s[j]).
  const n = s.length, full = (1 << n) - 1;
  let start = 0;
  for (let j = 0; j < n; j++) if (s[j] === '1') start |= 1 << j;
  const dist = new Array(full + 1).fill(Infinity);
  dist[start] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let mask = 0; mask <= full; mask++) {
      if (dist[mask] === Infinity) continue;
      for (let i = 0; i < n; i++) {
        const prefix = mask ^ ((1 << (i + 1)) - 1);
        if (dist[mask] + i + 1 < dist[prefix]) { dist[prefix] = dist[mask] + i + 1; changed = true; }
        const suffix = mask ^ (full ^ ((1 << i) - 1));
        if (dist[mask] + n - i < dist[suffix]) { dist[suffix] = dist[mask] + n - i; changed = true; }
      }
    }
  }
  return Math.min(dist[0], dist[full]);
}

