function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 10);
  const style = Math.floor(rand() * 4);
  let s = '';
  let bit = rand() < 0.5 ? '0' : '1';
  for (let j = 0; j < n; j++) {
    if (style === 0) bit = rand() < 0.5 ? '0' : '1';
    else if (style === 1) bit = j === 0 ? bit : (bit === '0' ? '1' : '0');
    else if (style === 2) { if (rand() < (size === 'large' ? 0.01 : 0.25)) bit = bit === '0' ? '1' : '0'; }
    else if (j > 0 && rand() < 0.1) bit = bit === '0' ? '1' : '0';
    s += bit;
  }
  return [s];
}
